
CREATE OR REPLACE VIEW analytics.vw_monthly_sales AS SELECT d.calendar_year, d.month_number, d.month_name, COUNT(DISTINCT f.order_id) AS total_orders, COUNT(DISTINCT f.order_item_id) AS total_order_items, SUM(f.quantity) AS total_units_sold, ROUND(SUM(f.sales), 2) AS total_recorded_sales, ROUND(SUM(f.discount), 2) AS total_discounts, ROUND(SUM(f.order_item_total), 2) AS total_net_item_value, ROUND(SUM(f.order_item_total) / NULLIF(COUNT(DISTINCT f.order_id), 0), 2) AS average_order_value, ROUND(100.0 * SUM(f.discount) / NULLIF(SUM(f.sales), 0), 2) AS discount_rate_pct FROM analytics.fact_order_items f INNER JOIN analytics.dim_date d ON f.order_date_key = d.date_key GROUP BY d.calendar_year, d.month_number, d.month_name;
